namespace sv_184efb43dd914862906285642828224d.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Status,
    string Location);

using sv_184efb43dd914862906285642828224d.Client.Models;

namespace sv_184efb43dd914862906285642828224d.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_184efb43dd914862906285642828224d.Client.Models;
using sv_184efb43dd914862906285642828224d.Client.Services;

namespace sv_184efb43dd914862906285642828224d.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Seeds = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            "PKG-001",
            "In Transit",
            "Chicago, IL",
            new DateTimeOffset(2026, 7, 12, 17, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 7, 7, 8, 0, 0, TimeSpan.Zero), "Picked Up", "New York, NY"),
                new(new DateTimeOffset(2026, 7, 8, 14, 30, 0, TimeSpan.Zero), "In Transit", "Philadelphia, PA"),
                new(new DateTimeOffset(2026, 7, 9, 9, 15, 0, TimeSpan.Zero), "In Transit", "Chicago, IL"),
            }),
        ["PKG-002"] = new Shipment(
            "PKG-002",
            "Delivered",
            "San Francisco, CA",
            new DateTimeOffset(2026, 7, 8, 12, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 7, 5, 10, 0, 0, TimeSpan.Zero), "Picked Up", "Seattle, WA"),
                new(new DateTimeOffset(2026, 7, 6, 16, 0, 0, TimeSpan.Zero), "In Transit", "Portland, OR"),
                new(new DateTimeOffset(2026, 7, 7, 20, 45, 0, TimeSpan.Zero), "Out for Delivery", "San Francisco, CA"),
                new(new DateTimeOffset(2026, 7, 8, 11, 30, 0, TimeSpan.Zero), "Delivered", "San Francisco, CA"),
            }),
        ["PKG-003"] = new Shipment(
            "PKG-003",
            "Processing",
            "Dallas, TX",
            new DateTimeOffset(2026, 7, 15, 18, 0, 0, TimeSpan.Zero),
            new List<StatusUpdate>
            {
                new(new DateTimeOffset(2026, 7, 9, 7, 0, 0, TimeSpan.Zero), "Processing", "Dallas, TX"),
            }),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);
        Seeds.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;
using sv_184efb43dd914862906285642828224d.Client.Models;

namespace sv_184efb43dd914862906285642828224d.Client.Services;

public sealed class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_184efb43dd914862906285642828224d.Client.Models
@using sv_184efb43dd914862906285642828224d.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracking> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="not-found">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status Updates</h3>
        <table>
            <thead>
                <tr>
                    <th>Time</th>
                    <th>Status</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.Updates)
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Status</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed; do nothing.
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException || ex.CancellationToken != ct)
        {
            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

